def translate_note(text):
    for en,de in sorted(phrases.items(),key=lambda p:len(p[0]),reverse=True):
        text=re.sub(r'(?<![A-Za-z])'+re.escape(en)+r'(?![A-Za-z])',de,text,flags=re.I)
    return text

for block in blocks:
    folder=root/f'block-{block}'; report=json.loads((folder/'validation-report.json').read_text())
    output=Path(report['outputPath']); data=json.loads(output.read_text()); source=json.loads((folder/'source.json').read_text()); counts={'source_note':0,'savings':0}
    def walk(target,original):
        if isinstance(target,dict) and isinstance(original,dict):
            for key,item in target.items():
                src=original.get(key)
                if key=='source_note' and isinstance(item,str) and item:
                    target[key]=translate_note(item); counts[key]+=1
                elif key=='savings' and isinstance(src,str) and src:
                    target[key]=savings.get(src,src); counts[key]+=1
                elif key in original: walk(item,src)
        elif isinstance(target,list) and isinstance(original,list):
            for item,src in zip(target,original): walk(item,src)
    walk(data,source); output.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n'); print(block,counts)
